import{ListenWatch}from"../primitives/ListenWatch.js";class Props extends ListenWatch{constructor(){super(),this.name=this.id||this.nodeName.toLowerCase()}handle(event){let data=event.detail;if(!data)return;let index=this.fromElems.indexOf(event.target)+1;for(const[i,to]of this.toElems.entries())Object.keys(data).forEach((k,i)=>{to.style.setProperty(`--${this.name}-${index}-${k}`,data[k])})}handleWatch(list,observer){if(!this.bypass)for(const[i,to]of this.toElems.entries())for(const r of list){let index=this.fromElems.indexOf(r.target)+1;to.style.setProperty(`--${this.name}-${index}-${r.attributeName}`,r.target[r.attributeName])}}}export{Props};